// Run Once for All Items — receives all paginated pages
const pages = $input.all();
const client = $('Split in Batches').first().json;

// Flatten all campaigns from all pages
const allCampaigns = [];
for (const page of pages) {
  const items = page.json?.data;
  if (Array.isArray(items)) allCampaigns.push(...items);
}

if (allCampaigns.length === 0) {
  return [{ json: { sql: 'SELECT 1', count: 0, client_name: client.name } }];
}

const typeMap = {
  'outbound':      'outreach',
  'reply_followup': 'nurture',
};
const statusMap = {
  'active':    'active',
  'launching': 'launching',
  'draft':     'draft',
  'paused':    'stopped',
  'failed':    'stopped',
  'archived':  'completed',
  'completed': 'completed',
};

const safe = s => (s || '').replace(/'/g, "''");

const values = allCampaigns.map(c => {
  const type   = typeMap[c.type]     || 'outreach';
  const status = statusMap[c.status] || 'draft';
  const name   = safe(c.name);
  const dbSize = Number(c.total_leads)  || 0;
  const posRes = Number(c.interested)   || 0;
  const startDate = c.created_at ? `'${c.created_at.substring(0, 10)}'` : 'NULL';
  return `('${client.id}', '${c.id}', '${type}'::campaign_type, '${name}', '${status}'::campaign_status, ${dbSize}, ${posRes}, ${startDate})`;
}).join(',\n');

const sql = `
INSERT INTO campaigns
  (client_id, external_id, type, name, status, database_size, positive_responses, start_date)
VALUES
${values}
ON CONFLICT (external_id) DO UPDATE SET
  name               = EXCLUDED.name,
  status             = EXCLUDED.status,
  database_size      = EXCLUDED.database_size,
  positive_responses = EXCLUDED.positive_responses,
  updated_at         = NOW()
RETURNING external_id, name, status
`;

return [{ json: { sql, count: allCampaigns.length, client_name: client.name } }];
